const BINARY_PROBE_BYTES = 8000;
const HEADER_LINES = 10;
const COMMENT_START = /^\s*(\/\/|\/\*|\*|#|<!--|--)/;
const GENERATED_MARKERS = [/@generated\b/, /\bCode generated\b.*\bDO NOT EDIT\b/, /<auto-generated\b/i];

export function isBinary(content: Buffer): boolean {
  return content.subarray(0, BINARY_PROBE_BYTES).includes(0);
}

// Only comment lines at the top of the file are checked, so source that merely mentions
// "@generated" (a linter rule, a regex, documentation) is not misclassified.
export function isGenerated(text: string): boolean {
  const header = text
    .split(/\r\n|\n|\r/, HEADER_LINES)
    .filter((line) => COMMENT_START.test(line))
    .join("\n");
  return GENERATED_MARKERS.some((marker) => marker.test(header));
}

export function countNonBlankLines(text: string): number {
  let count = 0;
  for (const line of text.split(/\r\n|\n|\r/)) if (line.trim() !== "") count++;
  return count;
}
